      {
        "start": 22.64,
        "end": 23.4,
        "text": "什么语气"
      },
      {
        "start": 23.4,
        "end": 24.8,
        "text": "最后要什么格式"
      },
      {
        "start": 24.8,
        "end": 25.88,
        "text": "比如工作总结"
      },
      {
        "start": 25.88,
        "end": 27.64,
        "text": "别只说帮我寫一份"
      },
      {
        "start": 27.64,
        "end": 28.88,
        "text": "你可以直接这样说"
      },
      {
        "start": 28.88,
        "end": 31.24,
        "text": "请根据我提供的真实工作内容"
      },
      {
        "start": 31.24,
        "end": 33.52,
        "text": "写一份阶段信工的总结"
      },
      {
        "start": 33.52,
        "end": 35.24,
        "text": "结构包括完成的内容"
      },
      {
        "start": 35.24,
        "end": 36.24,
        "text": "取得的结果"
      },
      {
        "start": 36.24,
        "end": 37.68,
        "text": "目前存在的问题"
      },
      {
        "start": 37.68,
        "end": 38.84,
        "text": "下一步计划"
      },
      {
        "start": 38.84,
        "end": 40.16,
        "text": "不要写空话套话"
      },
      {
        "start": 40.16,
        "end": 42.2,
        "text": "不要编造没有提供的数据"
      },
      {
        "start": 42.2,
        "end": 43.72,
