      },
      {
        "start": 46.84,
        "end": 48.84,
        "text": "我刚才用这条重新跑了一遍"
      },
      {
        "start": 48.84,
        "end": 50.68,
        "text": "出来的内容就具体多了"
      },
      {
        "start": 50.68,
        "end": 52.36,
        "text": "至少可以进入修改环节"
      },
      {
        "start": 52.36,
        "end": 53.6,
        "text": "我有把工作总结"
      },
      {
        "start": 53.6,
        "end": 54.44,
        "text": "工作汇报"
      },
      {
        "start": 54.44,
        "end": 55.2,
        "text": "会议记要"
      },
      {
        "start": 55.2,
        "end": 56.12,
        "text": "工作发案等等"
      },
      {
        "start": 56.12,
        "end": 57.32,
        "text": "这些常用场景"
      },
      {
        "start": 57.32,
        "end": 58.16,
        "text": "整理成了"
